import { Router } from "@angular/router";
import { ReCaptchaV3Service } from "ng-recaptcha";
import { EMPTY, exhaustMap, filter, Observable, Subject, tap } from "rxjs";
import { FormBuilder, Validators } from "@angular/forms";
import { Component, inject, ViewChild } from "@angular/core";

import { BcAlertComponent } from "@bancolombia/design-system-web/bc-alert";
import { BcDialogService } from "@bancolombia/design-system-web/bc-services";
import { BcOffCanvasComponent } from "@bancolombia/design-system-web/bc-off-canvas";

import { DocumentType, InitValuesFranchise } from "./formConfig";
import { LoaderComponent } from "../../components/loader/loader.component";
import { EncryptionService } from "../../../core/services/encryption.service";
import { PasswordActivationService } from "../../../core/services/password-activation.service";
import { catchError, take } from "rxjs/operators";

@Component({
  selector: "app-main",
  templateUrl: "./main.component.html",
  styleUrls: ["./main.component.css"],
})

/**
 * Represents the MainComponent class.
 * @export
 * @class MainComponent
 */
export class MainComponent {
  private encryptionService = inject(EncryptionService);
  private recaptchaService = inject(ReCaptchaV3Service);
  private passwordActivationService = inject(PasswordActivationService);

  private router = inject(Router);
  private fb = inject(FormBuilder);
  private dialogService = inject(BcDialogService);

  /**
   * Reference to the BcOffCanvasComponent.
   * @type {BcOffCanvasComponent}
   * @memberof MainComponent
   */
  @ViewChild("offCanvasComponent", { static: true })
  bcOffCanvasComponent!: BcOffCanvasComponent;

  @ViewChild("loaderComponent", { static: true })
  loaderComponent!: LoaderComponent;

  customerForm = this.fb.group({
    documentType: ["CC", Validators.required],
    documentNumber: ["", Validators.required],
    cardType: ["", Validators.required],
    cardNumber: ["", Validators.required],
  });

  submited$: Subject<void> = new Subject<void>();

  /**
   * The number of inputs in the form.
   * @type {number}
   * @memberof MainComponent
   */
  numInputs: number = 6;

  /**
   * Indicates whether the success message should be shown.
   * @type {boolean}
   * @memberof MainComponent
   */
  showSuccess: boolean = false;

  /**
   * Initializes the component.
   * @memberof MainComponent
   */
  ngOnInit(): void {
    this.subscribeToSubmit();
  }

  /**
   * The list of document types.
   * @type {Array<any>}
   * @memberof MainComponent
   */
  documentType = DocumentType;

  /**
   * The initial values for the franchise (Credit card input).
   * @type {Array<any>}
   * @memberof MainComponent
   */
  initValuesFranchise = InitValuesFranchise;

  /**
   * The values for search.
   * @type {Array<number>}
   * @memberof MainComponent
   */
  valuesSearch = [3, 4, 5, 91, 8, 55];

  /**
   * Opens the off-canvas component.
   * @memberof MainComponent
   */
  openOffCanvas() {
    this.bcOffCanvasComponent.openOffCanvas();
  }

  /**
   * Closes the off-canvas component.
   * @memberof MainComponent
   */
  closeOffCanvas() {
    this.bcOffCanvasComponent.closeOffCanvas(null);
  }

  /**
   * Submits the form.
   * @memberof MainComponent
   */
  subscribeToSubmit() {
    this.submited$
      .pipe(
        filter(() => this.customerForm.valid),
        tap(() => this.loaderComponent.show()),
        exhaustMap(() => this.handleRecaptcha()),
        catchError((error) => {
          this.loaderComponent.hide();
          this.handleError(error);
          return EMPTY;
        }),
      )
      .subscribe({
        next: (res) => this.handleSuccess(res),
        complete: () => this.loaderComponent.hide(),
      });
  }

  private handleRecaptcha(): Observable<any> {
    return this.recaptchaService.execute("submit").pipe(
      exhaustMap((token) => {
        return this.passwordActivationService.validateCaptcha(token).pipe(
          tap((res: any) => {
            if (res.data.valid) {
              throw new Error("LowCaptchaScore");
            }
          }),
          exhaustMap(() => this.validateCustomerData()),
        );
      }),
    );
    // return this.validateCustomerData();
  }

  private validateCustomerData(): Observable<any> {
    const { documentType, documentNumber, cardType, cardNumber } =
      this.customerForm.value;

    const data = {
      requestId: this.encryptionService.generateUUID(),
      documentNumber: documentNumber?.toString(),
      documentType,
      cardType,
      sensitiveData: {
        cardNumber: cardNumber?.replace(/\s/g, ""),
      },
    };

    return this.passwordActivationService.customerValidation(data);
  }

  private handleSuccess(res: any): void {
    this.loaderComponent.hide();
    this.passwordActivationService.setTransactionId(res.data.transactionId);
    this.passwordActivationService.setInfoValidated(true);
    this.router.navigate(["/dynamic-key-verification"]);
  }

  private handleError(error: any): void {
    if (error.message === "LowCaptchaScore") {
      this.showAlert(
        "El puntaje del captcha es demasiado bajo. Por favor, intenta nuevamente.",
      );
      return;
    }

    if (error.error) {
      switch (error.error.listErrorDto.code) {
        case "SFB001":
          this.showAlert(
            "No dispones de una clave dinámica. Comunícate con nuestra sucursal telefónica.",
          );
          break;
        case "SFB002":
          this.showAlert(
            "Algunos datos son incorrectos, verifica la información e intenta nuevamente.",
          );
          break;
        case "SFB003":
          this.showAlert("Intentos de tarjeta fallidos.");
          break;
        default:
          this.showAlert("Ha ocurrido un error inesperado.");
          break;
      }
    } else {
      this.showAlert("Ha ocurrido un error inesperado.");
      this.router.navigate(["/dynamic-key-verification"]);
    }
  }

  showAlert(message: string) {
    const dialogRef = this.dialogService.open(BcAlertComponent, {
      type: "error",
      text: message,
      timeout: 60000,
    });
  }

  ngOnDestroy() {
    this.submited$.unsubscribe();
  }
}
